css:
@property --x {
  syntax: "<percentage>";
  inherits: true;
  initial-value: 50%;
}

@property --y {
  syntax: "<percentage>";
  inherits: true;
  initial-value: 50%;
}

/* Изоляция стилей карточки без использования глобальных селекторов */
.card,
.card * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family:
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    sans-serif;
}

.card {
  position: relative;
  width: 320px;
  border-radius: 24px;
  overflow: hidden;
  --x: 50%;
  --y: 50%;
  --spotlight-radius: 140px;
  box-shadow: 0 30px 60px rgba(0, 0, 0, 0.95);
  transition:
    --x 0.05s linear,
    --y 0.05s linear;
}

/* Слои карточки */
.card .card-layer {
  padding: 38px 30px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  border-radius: 24px;
}

/* 1. Базовый тёмный слой */
.card .card-dark {
  background-color: #09090c;
  border: 1px solid #121217;
}

.card .card-dark .badge {
  color: #26262e;
  background: #0f0f14;
  border: 1px solid #181820;
}

.card .card-dark .title {
  color: #1a1a20;
}

.card .card-dark .description {
  color: #16161b;
}

.card .card-dark .btn {
  background: #0d0d12;
  color: #2e2e38;
  border: 1px solid #181822;
}

/* 2. Подсвеченный слой */
.card .card-lit {
  position: absolute;
  inset: 0;
  background-color: #16161f;
  border: 1px solid rgba(255, 255, 255, 0.35);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.25s ease;

  -webkit-mask-image: radial-gradient(
    circle var(--spotlight-radius) at var(--x) var(--y),
    black 0%,
    rgba(0, 0, 0, 0.7) 35%,
    rgba(0, 0, 0, 0.2) 65%,
    transparent 100%
  );
  mask-image: radial-gradient(
    circle var(--spotlight-radius) at var(--x) var(--y),
    black 0%,
    rgba(0, 0, 0, 0.7) 35%,
    rgba(0, 0, 0, 0.2) 65%,
    transparent 100%
  );
}

.card .card-lit .badge {
  color: #e4e4e7;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.card .card-lit .title {
  color: #ffffff;
  text-shadow: 0 0 25px rgba(255, 255, 255, 0.5);
}

.card .card-lit .description {
  color: #a1a1aa;
}

.card .card-lit .btn {
  background: rgba(255, 255, 255, 0.06);
  color: #d1d1d6;
  border: 1px solid rgba(255, 255, 255, 0.25);
}

.card:hover .card-lit {
  opacity: 1;
}

/* Стили элементов */
.card .badge {
  align-self: flex-start;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 99px;
}

.card .title {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.2;
}

.card .description {
  font-size: 14px;
  line-height: 1.6;
}

.card .btn {
  margin-top: 6px;
  padding: 12px 20px;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.5px;
  cursor: pointer;
  position: relative;
  z-index: 20;
  transition: all 0.25s ease;
}

/* Свечение надписи при наведении */
.card .card-dark .btn:hover,
.card:has(.btn:hover) .card-lit .btn {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.8);
  text-shadow:
    0 0 6px #ffffff,
    0 0 15px rgba(255, 255, 255, 0.9),
    0 0 25px rgba(255, 255, 255, 0.6),
    0 0 40px rgba(255, 255, 255, 0.4);
  box-shadow:
    0 0 20px rgba(255, 255, 255, 0.35),
    inset 0 0 12px rgba(255, 255, 255, 0.2);
  transform: translateY(-2px);
}

/* 3. Трекинг 10x10 */
.card .tracker {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  grid-template-rows: repeat(10, 1fr);
  z-index: 10;
}

.card .tracker span {
  display: block;
  width: 100%;
  height: 100%;
}

/* Y-координаты */
.card:has(.tracker span:nth-child(-n + 10):hover) {
  --y: 5%;
}
.card:has(.tracker span:nth-child(n + 11):nth-child(-n + 20):hover) {
  --y: 15%;
}
.card:has(.tracker span:nth-child(n + 21):nth-child(-n + 30):hover) {
  --y: 25%;
}
.card:has(.tracker span:nth-child(n + 31):nth-child(-n + 40):hover) {
  --y: 35%;
}
.card:has(.tracker span:nth-child(n + 41):nth-child(-n + 50):hover) {
  --y: 45%;
}
.card:has(.tracker span:nth-child(n + 51):nth-child(-n + 60):hover) {
  --y: 55%;
}
.card:has(.tracker span:nth-child(n + 61):nth-child(-n + 70):hover) {
  --y: 65%;
}
.card:has(.tracker span:nth-child(n + 71):nth-child(-n + 80):hover) {
  --y: 75%;
}
.card:has(.tracker span:nth-child(n + 81):nth-child(-n + 90):hover) {
  --y: 85%;
}
.card:has(.tracker span:nth-child(n + 91):nth-child(-n + 100):hover) {
  --y: 95%;
}

/* X-координаты */
.card:has(.tracker span:nth-child(10n + 1):hover) {
  --x: 5%;
}
.card:has(.tracker span:nth-child(10n + 2):hover) {
  --x: 15%;
}
.card:has(.tracker span:nth-child(10n + 3):hover) {
  --x: 25%;
}
.card:has(.tracker span:nth-child(10n + 4):hover) {
  --x: 35%;
}
.card:has(.tracker span:nth-child(10n + 5):hover) {
  --x: 45%;
}
.card:has(.tracker span:nth-child(10n + 6):hover) {
  --x: 55%;
}
.card:has(.tracker span:nth-child(10n + 7):hover) {
  --x: 65%;
}
.card:has(.tracker span:nth-child(10n + 8):hover) {
  --x: 75%;
}
.card:has(.tracker span:nth-child(10n + 9):hover) {
  --x: 85%;
}
.card:has(.tracker span:nth-child(10n + 10):hover) {
  --x: 95%;
}
